import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Delete a Space","description":"Deleting a Space — what disappears and what to do beforehand.","frontmatter":{"title":"Delete a Space","description":"Deleting a Space — what disappears and what to do beforehand."},"headers":[],"relativePath":"en/spaces/space-loeschen.md","filePath":"en/spaces/space-loeschen.md","lastUpdated":1787319236000}'),n={name:"en/spaces/space-loeschen.md"};function r(i,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="delete-a-space" tabindex="-1">Delete a Space <a class="header-anchor" href="#delete-a-space" aria-label="Permalink to &quot;Delete a Space&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">A deleted Space takes everything with it</p><p>Deleting the Space removes <strong>all</strong> the Grids inside it, entries included, along with all Views, Forms, Pages, Portals, and Flows.</p><p>There&#39;s <strong>no recovery</strong> within the app. Check the points below before you delete.</p></div><h2 id="check-beforehand" tabindex="-1">Check beforehand <a class="header-anchor" href="#check-beforehand" aria-label="Permalink to &quot;Check beforehand&quot;">​</a></h2><h3 id="_1-·-back-up-your-data" tabindex="-1">1 · Back up your data <a class="header-anchor" href="#_1-·-back-up-your-data" aria-label="Permalink to &quot;1 · Back up your data&quot;">​</a></h3><p>Pull a <a href="/en/grids/csv-export">CSV export</a> from every Grid whose data you want to keep.</p><div class="warning custom-block"><p class="custom-block-title">What the export doesn&#39;t include</p><ul><li><strong>File attachments</strong> — download these separately</li><li><strong>Links</strong> — come through as display text, not as a reference</li><li><strong>Calculated fields</strong> — come through as a value, not the calculation itself</li><li><strong>Structure</strong> — Views, Forms, Flows, and Pages can&#39;t be exported</li></ul><p>For a migration, a CSV export is therefore not a complete backup. Document the structure if you plan to rebuild it elsewhere.</p></div><h3 id="_2-·-check-external-links" tabindex="-1">2 · Check external links <a class="header-anchor" href="#_2-·-check-external-links" aria-label="Permalink to &quot;2 · Check external links&quot;">​</a></h3><p>Open <strong>Space settings → Links</strong>. It lists every externally open access point.</p><p>Every one of them stops working:</p><table tabindex="0"><thead><tr><th>Link type</th><th>Consequence</th></tr></thead><tbody><tr><td>Form links</td><td>Distributed forms stop working</td></tr><tr><td>View links</td><td>Shared views are gone</td></tr><tr><td>Portals</td><td>Embedded pages on your website stay blank</td></tr><tr><td>Flow start</td><td>External systems calling the flow hit a dead end</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Especially critical: printed QR codes and embedded portals</p><p>A QR code on a poster or a portal embedded in your website can&#39;t be recalled. Both point to nothing once deleted.</p><p>Check where such links are in circulation before you delete.</p></div><h3 id="_3-·-inform-people" tabindex="-1">3 · Inform people <a class="header-anchor" href="#_3-·-inform-people" aria-label="Permalink to &quot;3 · Inform people&quot;">​</a></h3><p>Under <strong>Share Space</strong>, look at <strong>Shared with</strong> to see who has access. For these people, the Space simply disappears without warning; opening it just shows <em>This Space has been deleted</em>.</p><h3 id="_4-·-dependencies-in-other-spaces" tabindex="-1">4 · Dependencies in other Spaces <a class="header-anchor" href="#_4-·-dependencies-in-other-spaces" aria-label="Permalink to &quot;4 · Dependencies in other Spaces&quot;">​</a></h3><p>Links only work within a single Space, but a Flow or Page in <strong>another</strong> Space can point to this content via an HTTP call or internal reference. Check for this if you work across multiple Spaces.</p><h2 id="deleting" tabindex="-1">Deleting <a class="header-anchor" href="#deleting" aria-label="Permalink to &quot;Deleting&quot;">​</a></h2><ol><li>Open the Space menu.</li><li>Choose <strong>Delete Space</strong>.</li><li>Confirm in the dialog, which shows the Space name in red.</li></ol><h2 id="alternatives-to-deleting" tabindex="-1">Alternatives to deleting <a class="header-anchor" href="#alternatives-to-deleting" aria-label="Permalink to &quot;Alternatives to deleting&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Archiving is often the better choice</p><table tabindex="0"><thead><tr><th>Instead of deleting …</th><th>Do this</th></tr></thead><tbody><tr><td>Space is no longer needed</td><td>Assign the category &quot;Archive&quot; and set the color to gray</td></tr><tr><td>No one should write to it anymore</td><td>Set all roles to <strong>View</strong> — this also frees up seats</td></tr><tr><td>Only the links should go</td><td>Remove individual links in the links overview, keep the Space</td></tr><tr><td>Reduce costs</td><td>Downgrade the plan instead of deleting</td></tr></tbody></table><p>An archived Space uses no seats as long as no one has editing rights — and the data stays available if it&#39;s ever needed again.</p></div><h2 id="who-can-delete" tabindex="-1">Who can delete <a class="header-anchor" href="#who-can-delete" aria-label="Permalink to &quot;Who can delete&quot;">​</a></h2><p>Deleting requires the appropriate rights. If the menu item is missing, your <a href="/en/zusammenarbeit/rollen">role</a> isn&#39;t sufficient.</p><h2 id="what-affected-people-see" tabindex="-1">What affected people see <a class="header-anchor" href="#what-affected-people-see" aria-label="Permalink to &quot;What affected people see&quot;">​</a></h2><p>After deletion, anyone who still has a link or bookmark sees:</p><blockquote><p><em>This Space has been deleted</em></p></blockquote><p>If access was revoked instead — without deletion — the message reads:</p><blockquote><p><em>You no longer have access to this Space.</em></p></blockquote><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/csv-export">CSV export</a></li><li><a href="/en/zusammenarbeit/externe-links">External links at a glance</a></li><li><a href="/en/zusammenarbeit/sitzplaetze">Seats</a></li></ul>',28)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
